	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.ioTDeviceSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for IoTDevice : " + successValue.getIoTDeviceId());
							  if (successValue.getIoTDeviceId().equals(ioTDeviceId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfIoTDeviceList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("IoTDevice test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on ioTDevice consumed")
					);
			subscriber.ioTDeviceSubscribe( ioTDeviceId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for IoTDevice : " + successValue.getIoTDeviceId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfIoTDeviceList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on ioTDevice for ioTDeviceId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a IoTDevice. 
	 */
	protected IoTDevice read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created IoTDevice" );

		IoTDevice entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read IoTDevice with primary key" );
		msg.append( ioTDeviceId );
		
		IoTDeviceFetchOneSummary fetchOneSummary = new IoTDeviceFetchOneSummary( ioTDeviceId );

		try {
			entity = IoTDeviceService.getIoTDeviceInstance().getIoTDevice( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found IoTDevice " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a IoTDevice.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a IoTDevice." );

		StringBuilder msg = new StringBuilder( "Failed to update a IoTDevice : " );        
		IoTDevice entity = read();
		UpdateIoTDeviceCommand command = generateUpdateCommand();
		command.setIoTDeviceId(entity.getIoTDeviceId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created IoTDevice." );

			// for use later on...
			ioTDeviceId = entity.getIoTDeviceId();

			IoTDeviceService proxy = IoTDeviceService.getIoTDeviceInstance();  

			proxy.updateIoTDevice( command ).get();

			LOGGER.info( "-- Successfully saved IoTDevice - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + ioTDeviceId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a IoTDevice.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created IoTDevice." );

		IoTDevice entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read IoTDevice with id " + ioTDeviceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read IoTDevice with id " + ioTDeviceId );

			throw e;
		}

		try{
			IoTDeviceService.getIoTDeviceInstance().delete( new DeleteIoTDeviceCommand( entity.getIoTDeviceId() ) ).get();
			LOGGER.info( "-- Successfully deleted IoTDevice with id " + ioTDeviceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete IoTDevice with id " + ioTDeviceId );

			throw e;
		}
	}

	/**
	 * get all IoTDevices.
	 */
	protected List<IoTDevice> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of IoTDevices:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all IoTDevice : " );        
		List<IoTDevice> collection  = new ArrayList<>();

		try {
			// call the static get method on the IoTDeviceService
			collection = IoTDeviceService.getIoTDeviceInstance().getAllIoTDevice();
			assertNotNull( collection, "An Empty collection of IoTDevice was incorrectly returned.");
			
			// Now print out the values
			IoTDevice entity = null;            
			Iterator<IoTDevice> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getIoTDeviceId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

